SELECT





ORDER BY s.day_of_week, s.start_section
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM schedule
WHERE teacher_id = #{teacherId}
  AND day_of_week = #{dayOfWeek}
  AND start_section <= #{endSection}
  AND end_section >= #{startSection}
  AND semester = #{semester}
  AND year = #{year}

      AND id != #{excludeId}

SELECT COUNT(*)
FROM schedule
WHERE class_id = #{classId}
  AND day_of_week = #{dayOfWeek}
  AND start_section <= #{endSection}
  AND end_section >= #{startSection}
  AND semester = #{semester}
  AND year = #{year}

      AND id != #{excludeId}

SELECT COUNT(*)
FROM schedule
WHERE classroom = #{classroom}
  AND day_of_week = #{dayOfWeek}
  AND start_section <= #{endSection}
  AND end_section >= #{startSection}
  AND semester = #{semester}
  AND year = #{year}

      AND id != #{excludeId}

SELECT COUNT(*)
FROM student
WHERE class_id = #{classId}
